  /**
   * allTasks iterates over GET /v1/xdsl/{serviceName}/tasks (List the tasks of an xDSL access).
   *
   * It lists the IDs with {@link XdslApi.listTasks}, then gets each object with
   * {@link XdslApi.getTasks}, only when the loop reaches it. An object deleted in the
   * meantime is skipped. Any other error is thrown and stops the loop.
   *
   * The two calls require the IAM action xdsl:apiovh:tasks/get.
   *
   * @param serviceName - Service name
   * @param params - the optional parameters
   * @param options - the options of this call: signal, timeout, headers
   * @returns each {@link models.XdslTask}, one at a time: loop with `for await`
   * @throws ForbiddenError when the policy lacks an IAM action this call requires
   * @example
   * for await (const item of client.xdsl.allTasks(serviceName)) console.log(item);
   */
  allTasks(
    serviceName: string,
    params?: {
      /** Filter the value of function property (=) */
      function?: string | undefined;
      /** Include archived tasks */
      includeArchived?: boolean | undefined;
      /** Limit query result, default 20, max 50 */
      limit?: number | undefined;
      /** Filter the value of status property (=) */
      status?: models.XdslTaskStatusEnum | undefined;
    },
    options?: RequestOptions,
  ): AsyncIterable<models.XdslTask> {
    return this._each(
      () => this.listTasks(serviceName, params, options),
      (listedId) => this.getTasks(serviceName, listedId, options),
    );
  }

